const item = $input.item.json;
return {
  json: {
    flightStatusRows: item.values || []
  }
};

const item = $input.item.json;
return {
  json: {
    bookingRows: item.values || []
  }
};

const item = $input.item.json;
const statusRows = (item.flightStatusRows || []).slice(1); // skip header
const bookingRows = (item.bookingRows || []).slice(1); // skip header

// FlightStatus columns: [flightNumber, origin, destination, scheduledDeparture, status, delayMinutes, aircraft, lastUpdated]
// Bookings columns: [bookingId, passengerName, phone, email, flightNumber, cabinClass, loyaltyTier, seat, status]

const statusByFlight = {};
statusRows.forEach(r => {
  statusByFlight[r[0]] = {
    flightNumber: r[0] || '',
    origin: r[1] || '',
    destination: r[2] || '',
    scheduledDeparture: r[3] || '',
    status: r[4] || 'Unknown',
    delayMinutes: parseInt(r[5], 10) || 0,
    aircraft: r[6] || '',
    lastUpdated: r[7] || ''
  };
});

const bookings = bookingRows
  .filter(r => (r[8] || '').toLowerCase() === 'active')
  .map(r => {
    const flightNumber = r[4] || '';
    const flight = statusByFlight[flightNumber] || {};
    const status = flight.status || 'Unknown';
    const delayMinutes = flight.delayMinutes || 0;

    let impactLevel = 'On Time';
    if (status.toLowerCase() === 'cancelled') impactLevel = 'Cancelled';
    else if (delayMinutes >= 120) impactLevel = 'Severe Delay';
    else if (delayMinutes >= 45) impactLevel = 'Minor Delay';

    return {
      bookingId: r[0] || '',
      passengerName: r[1] || '',
      phone: r[2] || '',
      email: r[3] || '',
      flightNumber,
      cabinClass: r[5] || '',
      loyaltyTier: r[6] || '',
      seat: r[7] || '',
      origin: flight.origin || '',
      destination: flight.destination || '',
      scheduledDeparture: flight.scheduledDeparture || '',
      flightStatus: status,
      delayMinutes,
      impactLevel
    };
  });

return { json: { bookings, checkedAt: new Date().toISOString() } };

const item = $input.item.json;
const loggedAt = new Date().toISOString();

return {
  json: {
    ...item,
    loggedAt,
    opsLogRow: [
      loggedAt,
      item.bookingId || '',
      item.passengerName || '',
      item.flightNumber || '',
      item.flightStatus || '',
      item.delayMinutes || 0,
      item.impactLevel || '',
      item.origin || '',
      item.destination || ''
    ]
  }
};

const item = $input.item.json;
const invRows = (item.values || []).slice(1); // skip header

// Inventory columns: [flightNumber, origin, destination, departureTime, arrivalTime, seatsAvailable, cabinClassesAvailable]

const candidateFlights = invRows
  .filter(r =>
    r[1] === item.origin &&
    r[2] === item.destination &&
    r[0] !== item.flightNumber &&
    (parseInt(r[5], 10) || 0) > 0 &&
    (r[6] || '').toLowerCase().includes((item.cabinClass || '').toLowerCase())
  )
  .map(r => ({
    flightNumber: r[0] || '',
    origin: r[1] || '',
    destination: r[2] || '',
    departureTime: r[3] || '',
    arrivalTime: r[4] || '',
    seatsAvailable: parseInt(r[5], 10) || 0,
    cabinClassesAvailable: r[6] || ''
  }))
  .sort((a, b) => new Date(a.departureTime) - new Date(b.departureTime))
  .slice(0, 5);

return { json: { ...item, candidateFlights } };

parameters.text:
=You are an airline IROPS (irregular operations) rebooking specialist.

Passenger: {{ $json.passengerName }} (Booking {{ $json.bookingId }})
Loyalty Tier: {{ $json.loyaltyTier }}
Cabin Class: {{ $json.cabinClass }}
Original Flight: {{ $json.flightNumber }} ({{ $json.origin }} to {{ $json.destination }})
Scheduled Departure: {{ $json.scheduledDeparture }}
Flight Status: {{ $json.flightStatus }} (Impact: {{ $json.impactLevel }}, Delay: {{ $json.delayMinutes }} minutes)

Candidate Alternative Flights (same route, seats available, matching cabin class):
{{ JSON.stringify($json.candidateFlights) }}

Select the single best alternative flight for this passenger, prioritizing the earliest reasonable departure that protects their cabin class. If no candidates are available, say so honestly rather than inventing one.

Write a short, calm, reassuring notification suitable for SMS that tells the passenger what happened and what their new flight is (or that the team is actively working on options if none exist yet).

Return a JSON object with EXACTLY these fields:
{
  "selectedFlightNumber": "Flight number from the candidates, or empty string if none available",
  "selectedDepartureTime": "Departure time of the selected flight, or empty string if none available",
  "rebookingReason": "One sentence explaining the rebooking decision",
  "notificationMessage": "Under 200 characters, suitable for SMS",
  "alternativeOffered": true or false
}

Return ONLY the JSON. No markdown, no explanation.

parameters.jsCode:
const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  const alt = (item.candidateFlights && item.candidateFlights[0]) || null;
  if (alt) {
    parsed = {
      selectedFlightNumber: alt.flightNumber,
      selectedDepartureTime: alt.departureTime,
      rebookingReason: `Automatic rebooking due to ${(item.impactLevel || '').toLowerCase()} on ${item.flightNumber}.`,
      notificationMessage: `Your flight ${item.flightNumber} was affected (${item.impactLevel}). We've rebooked you on flight ${alt.flightNumber} departing ${alt.departureTime}.`,
      alternativeOffered: true
    };
  } else {
    parsed = {
      selectedFlightNumber: '',
      selectedDepartureTime: '',
      rebookingReason: `No alternative flights currently available for ${item.flightNumber}.`,
      notificationMessage: `Your flight ${item.flightNumber} was affected (${item.impactLevel}). Our team is finding you the next available option and will update you shortly.`,
      alternativeOffered: false
    };
  }
}
return {
  json: {
    ...item,
    ...parsed
  }
};

const item = $input.item.json;
const rebookedAt = new Date().toISOString();

return {
  json: {
    ...item,
    rebookedAt,
    rebookingLogRow: [
      rebookedAt,
      item.bookingId || '',
      item.passengerName || '',
      item.flightNumber || '',
      item.selectedFlightNumber || '',
      item.selectedDepartureTime || '',
      item.rebookingReason || '',
      item.alternativeOffered ? 'Yes' : 'No'
    ]
  }
};
